+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every whitespace-separated term of {@code name}
+ * appears in its first or last name, ignoring case and accents, and, if any
+ * statuses are given, its status is one of them.
+ *
+ * @param name     free text; blank matches every customer
+ * @param statuses statuses to keep; empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : WHITESPACE.matcher(name.strip()).replaceAll(" ");
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    /** {@code true} if this filter matches every customer. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The normalized search terms of the name filter. */
+    public List<String> terms() {
+        return name.isEmpty()
+                ? List.of()
+                : Arrays.stream(WHITESPACE.split(name)).map(CustomerFilter::fold).toList();
+    }
+
+    /** Folds case and accents so that, for example, {@code Mäkinen} becomes {@code makinen}. */
+    public static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return MARKS.matcher(decomposed).replaceAll("")
+                .toLowerCase(Locale.ROOT)
+                .replace("ø", "o")
+                .replace("æ", "ae")
+                .replace("œ", "oe")
+                .replace("ß", "ss")
+                .replace("ł", "l")
+                .replace("đ", "d");
+    }
+}
